class Solution {
    /**
     * Checks if a number is a power of three.
     *
     * @param n The integer to check.
     * @return True if n is a power of three, false otherwise.
     */
    public boolean isPowerOfThree(int n) {
        if (n <= 0) {
            return false;
        }

        // Efficiently check if n is a power of three using bit manipulation.
        // A power of three in binary has only one bit set to 1.
        // We repeatedly divide n by 3 until it's no longer divisible.
        // If it's a power of three, it will eventually become 1.
        while (n % 3 == 0) {
            n /= 3;
        }

        return n == 1;
    }
}
